namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and education. She specializes in programming pedagogy and has published extensively on teaching methods for introductory CS courses.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an ACM Distinguished Member with research interests in algorithm optimization and computational complexity theory.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, Code = "CS 350", Title = "Database Systems", Description = "Design and implementation of database management systems. Covers relational model, SQL, normalization, transaction processing, and NoSQL databases.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez worked at Oracle for 10 years before joining academia. Her research focuses on distributed database systems and query optimization.", IsFeatured = false, DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is a recipient of the university's Excellence in Teaching award. He makes complex mathematical concepts accessible through real-world applications.", IsFeatured = true, DepartmentName = "Mathematics" },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 220", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and engineering.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research spans applied mathematics and machine learning. She brings industry experience from her consulting work with tech companies.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is a former NASA researcher with expertise in astrophysics. He brings his passion for space science into the classroom.", IsFeatured = true, DepartmentName = "Physics" },
            new() { Id = 7, DepartmentId = 3, Code = "PHYS 250", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, uncertainty principle, and applications to atomic physics.", Credits = 3, Schedule = "TTh 9:00–10:15 AM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma is a leading researcher in quantum computing and has published over 50 papers in top physics journals.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 8, DepartmentId = 4, Code = "ENG 110", Title = "College Writing", Description = "Develop critical reading, analytical thinking, and academic writing skills. Focus on argumentation, research methods, and clear prose.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Prof. Diana Cole", InstructorBio = "Prof. Cole is a published author and writing coach. She has helped thousands of students develop their writing voice over her 20-year career.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 9, DepartmentId = 4, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary traditions from the colonial period to the present. Explores themes of identity, democracy, and social change.", Credits = 3, Schedule = "TTh 1:00–2:15 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres specializes in 20th-century American fiction and has authored two books on the Harlem Renaissance.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 10, DepartmentId = 5, Code = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to the present. Examines political, economic, social, and cultural developments.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Katherine Webb", InstructorBio = "Dr. Webb is an archaeologist and historian who has led excavations in Greece and Egypt. She brings artifacts and primary sources into the classroom.", IsFeatured = true, DepartmentName = "History" },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.DepartmentName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

