@page "/enroll"
@inject CourseCatalog.Services.CatalogService CatalogService
@attribute [RenderModeAttribute(typeof(Microsoft.AspNetCore.Components.Web.NoRenderMode))]

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Your enrollment request has been received. You will be contacted with confirmation details.</p>
    </div>
    <a href="/courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <p>Complete the form below to request enrollment in a course.</p>

    <form method="post" action="/enroll">
        <AntiforgeryToken />
        <input type="hidden" name="_handler" value="enrollment" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required placeholder="e.g., STU-12345" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select" required>
                <option value="">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(course.Id == Model.CourseId)">@course.Code — @course.Title</option>
                }
            </select>
        </div>

        @if (validationError)
        {
            <div class="alert alert-danger">Please fill in all fields and select a valid course.</div>
        }

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
        <a href="/courses" class="btn btn-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm(FormName = "enrollment")]
    public CourseCatalog.Models.EnrollmentRequest? Model { get; set; }

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromQuery]
    public bool Submitted { get; set; }

    private List<CourseCatalog.Models.Course> courses = new();
    private bool validationError;

    protected override void OnInitialized()
    {
        Model ??= new();
        courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }
}

